	'pr4_d' => 'Door, tracks, motor, fitting and removal.',
	'pr4_i' => 'Insulated sectional overhead door, up to 4 × 4.5 m',
	'pr4_p' => '€5,200',
	'pr5_d' => 'Shutter, release unit, fitting and removal.',
	'pr5_i' => 'Fire-rated roller shutter, up to 3 × 3 m',
